body.script:
// ===== VIDEOLAR: Archive.org havolalari =====
const VIDEOLAR = {
  "O'rgimchak Odam: Multiolam": { 480: "https://archive.org/download/uzbekmedia/VID_20260724_001540_534.mp4" },
  "O'rgimchak Odam: Uyga Yo'l Yo'q": { 480: "https://archive.org/download/uzbekmedia/VID_20260724_001540_534.mp4" },
  "Interstellar": { 480: "https://archive.org/download/uzbekmedia/VID_20260724_001540_534.mp4" },
  "Dune": { 480: "https://archive.org/download/uzbekmedia/VID_20260724_001540_534.mp4" },
  "Joker": { 480: "https://archive.org/download/uzbekmedia/VID_20260724_001540_534.mp4" },
  "Titanic": { 480: "https://archive.org/download/uzbekmedia/VID_20260724_001540_534.mp4" }
};

const kinolar = [
{ nom: "O'rgimchak Odam: Multiolam", yil: 2023, janr: "Animatsiya", reyting: 8.6, yangi: true, rasm: "https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg", tavsif: "Miles Morales multiolam bo'ylab sayohat qiladi.", treyler: "https://www.youtube.com/results?search_query=spider+man+across+the+spider+verse+trailer" },
{ nom: "O'rgimchak Odam: Uyga Yo'l Yo'q", yil: 2021, janr: "Aksiya", reyting: 8.2, yangi: false, rasm: "https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg", tavsif: "Piter Parker multiolamni buzadi.", treyler: "https://www.youtube.com/results?search_query=spider+man+no+way+home+trailer" },
{ nom: "Interstellar", yil: 2014, janr: "Fantastika", reyting: 8.7, yangi: false, rasm: "https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg", tavsif: "Kosmos bo'ylab sayohat.", treyler: "https://www.youtube.com/results?search_query=interstellar+trailer" },
{ nom: "Dune", yil: 2021, janr: "Fantastika", reyting: 8.0, yangi: true, rasm: "https://image.tmdb.org/t/p/w500/d5NXSklXo0qyIYkgV94XAgMIckC.jpg", tavsif: "Pol Atreydes cho'l sayyorasida.", treyler: "https://www.youtube.com/results?search_query=dune+trailer" },
{ nom: "Joker", yil: 2019, janr: "Drama", reyting: 8.4, yangi: false, rasm: "https://image.tmdb.org/t/p/w500/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg", tavsif: "Artur Flek Jokerga aylanadi.", treyler: "https://www.youtube.com/results?search_query=joker+trailer" },
{ nom: "Titanic", yil: 1997, janr: "Drama", reyting: 7.9, yangi: false, rasm: "https://image.tmdb.org/t/p/w500/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg", tavsif: "Titanik kemasida muhabbat.", treyler: "https://www.youtube.com/results?search_query=titanic+trailer" }
];

let sevimlilar = JSON.parse(localStorage.getItem('sevimlilar') || '[]');
let davomVaqtlari = JSON.parse(localStorage.getItem('davomVaqtlari') || '{}');
let sifatTanlov = localStorage.getItem('sifatTanlov') || 'auto';
let joriyJanr = 'hammasi';
let joriyKinoIndex = null;

function vaqtFormat(sek){if(!sek||isNaN(sek))return'00:00';const m=Math.floor(sek/60);const s=Math.floor(sek%60);return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}

function tezlikAniqla(){
const c=navigator.connection||navigator.mozConnection||navigator.webkitConnection;
if(!c)return{tezlik:'480',nom:"Aniqlanmadi, 480p"};
const t=c.effectiveType||'';const mb=c.downlink||0;
if(t==='slow-2g'||t==='2g'||mb<.5)return{tezlik:'360',nom:"🐢 Sekin (2G), 360p"};
if(t==='3g'||mb<2)return{tezlik:'480',nom:"📶 O'rtacha (3G), 480p"};
if(t==='4g'&&mb>=10)return{tezlik:'1080',nom:"⚡ Juda tez, 1080p"};
if(t==='4g'||mb>=2)return{tezlik:'720',nom:"🚀 Tez (4G), 720p"};
return{tezlik:'480',nom:"Aniqlanmadi, 480p"}
}

function renderKinolar(list, cid){
const c=document.getElementById(cid);c.innerHTML='';
if(list.length===0){c.innerHTML='
Kino topilmadi';return}
list.forEach(k=>{
const sev=sevimlilar.includes(k.nom);
const davom=davomVaqtlari[k.nom];
const div=document.createElement('div');div.className='kino-card';
const poster=document.createElement('div');poster.className='poster';
poster.onclick=()=>ochish(kinolar.indexOf(k));
poster.innerHTML=`${k.yangi?'YANGI':''}⭐ ${k.reyting}${davom?`▶ ${vaqtFormat(davom)}`:''}`;
const sb=document.createElement('button');sb.className='sevimli-btn'+(sev?' active':'');sb.textContent=sev?'❤️':'🤍';
sb.onclick=(e)=>{e.stopPropagation();e.preventDefault();sevimliToggle(k.nom)};poster.appendChild(sb);
const h3=document.createElement('h3');h3.textContent=k.nom;h3.onclick=()=>ochish(kinolar.indexOf(k));
const p=document.createElement('p');p.textContent=k.yil+' • '+k.janr;p.onclick=()=>ochish(kinolar.indexOf(k));
div.appendChild(poster);div.appendChild(h3);div.appendChild(p);c.appendChild(div)})}

function filtrla(){
const q=document.getElementById('search').value.toLowerCase();
const n=kinolar.filter(k=>{const mn=k.nom.toLowerCase().includes(q)||k.janr.toLowerCase().includes(q)||k.yil.toString().includes(q);const mj=joriyJanr==='hammasi'||k.janr===joriyJanr;return mn&&mj});
renderKinolar(n,'kinolar')}
document.getElementById('search').addEventListener('input',filtrla);
function filtr(j,b){joriyJanr=j;document.querySelectorAll('.janr-btn').forEach(x=>x.classList.remove('active'));b.classList.add('active');filtrla()}
function sevimliToggle(nom){const i=sevimlilar.indexOf(nom);if(i>-1)sevimlilar.splice(i,1);else sevimlilar.push(nom);localStorage.setItem('sevimlilar',JSON.stringify(sevimlilar));filtrla();renderSevimlilar()}
function renderSevimlilar(){const s=kinolar.filter(k=>sevimlilar.includes(k.nom));renderKinolar(s,'kinolar-sevimli')}

function videoYukla(nom,sifat){
const v=document.getElementById('videoPlayer');const vids=VIDEOLAR[nom];if(!vids)return;
let ts=sifat;
if(sifat==='auto'){const a=tezlikAniqla();ts=a.tezlik;document.getElementById('tezlikInfo').textContent=a.nom}
else{document.getElementById('tezlikInfo').textContent='🎞 Qo\'lda: '+sifat+'p'}
const m=vids[ts]||vids[480]||vids[360]||'';
if(m){v.src=m;v.load()}else{v.removeAttribute('src');v.load();document.getElementById('tezlikInfo').textContent='⚠️ Video hali qo\'shilmagan'}}

function sifatOzgartir(){
const s=document.getElementById('sifatSelect').value;sifatTanlov=s;localStorage.setItem('sifatTanlov',s);
if(joriyKinoIndex!==null){const k=kinolar[joriyKinoIndex];const v=document.getElementById('videoPlayer');const vt=v.currentTime;const p=!v.paused;videoYukla(k.nom,s);
v.addEventListener('loadedmetadata',function f(){v.currentTime=vt;if(p)v.play();v.removeEventListener('loadedmetadata',f)})}}

function ochish(i){
joriyKinoIndex=i;const k=kinolar[i];
document.getElementById('modal-nom').textContent=k.nom;
document.getElementById('modal-info').textContent=k.yil+' • '+k.janr;
document.getElementById('modal-reyting').textContent='⭐ Reyting: '+k.reyting;
document.getElementById('modal-tavsif').textContent=k.tavsif;
document.getElementById('modal-treyler').href=k.treyler;
document.getElementById('sifatSelect').value=sifatTanlov;
videoYukla(k.nom,sifatTanlov);
const db=document.getElementById('davomBtn');const sv=davomVaqtlari[k.nom];
if(sv&&sv>5){db.classList.remove('hidden');db.textContent='▶ Davom etish: '+vaqtFormat(sv)}else{db.classList.add('hidden')}
document.getElementById('modal').classList.add('active')}

function davomEt(){const k=kinolar[joriyKinoIndex];const v=document.getElementById('videoPlayer');v.currentTime=davomVaqtlari[k.nom]||0;v.play();document.getElementById('davomBtn').classList.add('hidden')}
function vaqtniSaqla(){const k=kinolar[joriyKinoIndex];const v=document.getElementById('videoPlayer');davomVaqtlari[k.nom]=v.currentTime;localStorage.setItem('davomVaqtlari',JSON.stringify(davomVaqtlari));alert('✅ Vaqt saqlandi: '+vaqtFormat(v.currentTime));filtrla()}

const videoEl=document.getElementById('videoPlayer');
videoEl.addEventListener('timeupdate',()=>{document.getElementById('vaqtJoriy').textContent=vaqtFormat(videoEl.currentTime)});
videoEl.addEventListener('loadedmetadata',()=>{document.getElementById('vaqtUmumiy').textContent=vaqtFormat(videoEl.duration)});
videoEl.addEventListener('pause',()=>{if(joriyKinoIndex!==null){const k=kinolar[joriyKinoIndex];if(videoEl.currentTime>5){davomVaqtlari[k.nom]=videoEl.currentTime;localStorage.setItem('davomVaqtlari',JSON.stringify(davomVaqtlari))}}});

let oxirgiBosish=0;
const videoBox=document.getElementById('videoBox');
const skipIndicator=document.getElementById('skipIndicator');
videoBox.addEventListener('click',(e)=>{if(e.target.tagName==='VIDEO'||e.target===videoBox){const h=Date.now();if(h-oxirgiBosish<400){videoEl.currentTime=Math.min(videoEl.currentTime+15,videoEl.duration);skipIndicator.classList.add('active');setTimeout(()=>skipIndicator.classList.remove('active'),1000);oxirgiBosish=0}else{oxirgiBosish=h}}});

function yopish(){const v=document.getElementById('videoPlayer');v.pause();document.getElementById('modal').classList.remove('active');filtrla();renderSevimlilar()}
function toggleTheme(){document.body.classList.toggle('light');const b=document.getElementById('themeBtn');b.textContent=document.body.classList.contains('light')?'☀️':'🌙';localStorage.setItem('tema',document.body.classList.contains('light')?'light':'dark')}
if(localStorage.getItem('tema')==='light'){document.body.classList.add('light');document.getElementById('themeBtn').textContent='☀️'}

function sahifa(n,b){document.querySelectorAll('.nav-btn').forEach(x=>x.classList.remove('active'));b.classList.add('active');
if(n==='bosh'){document.getElementById('sahifa-bosh').classList.remove('hidden');document.getElementById('sahifa-sevimli').classList.add('hidden')}
else{document.getElementById('sahifa-bosh').classList.add('hidden');document.getElementById('sahifa-sevimli').classList.remove('hidden');renderSevimlilar()}}

renderKinolar(kinolar,'kinolar');
renderSevimlilar();
